import 'package:flutter/material.dart';import 'package:get/get.dart';import '../../models/chat_message.dart';import 'chat_controller.dart';
class ConversationPage extends GetView<ChatController>{ConversationPage({super.key});final input=TextEditingController();@override Widget build(BuildContext context){final id=Get.parameters['id']??'';controller.loadMessages(id);return Scaffold(appBar:AppBar(title:Text(Get.parameters['title']??'Chat')),body:Column(children:[Expanded(child:Obx(()=>ListView.builder(reverse:true,padding:const EdgeInsets.all(12),itemCount:controller.messages.length,itemBuilder:(context,i){final m=controller.messages[i],mine=m.senderId=='current-user';return Align(alignment:mine?Alignment.centerRight:Alignment.centerLeft,child:Card(color:mine?Theme.of(context).colorScheme.primaryContainer:null,child:Padding(padding:const EdgeInsets.all(10),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[if(!mine)Text(m.senderDisplayName,style:Theme.of(context).textTheme.labelSmall),Text(m.body),if(m.status==MessageDeliveryStatus.pending)const Icon(Icons.schedule,size:12)]))));}))),SafeArea(child:Padding(padding:const EdgeInsets.all(8),child:Row(children:[Expanded(child:TextField(controller:input,decoration:const InputDecoration(hintText:'Message'))),IconButton(icon:const Icon(Icons.send),onPressed:(){controller.send(id,input.text);input.clear();})])))]));}}
